using UrlShortener.Core;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<ILinkStore, InMemoryLinkStore>();

var app = builder.Build();

// Create a short link for an absolute http/https URL, optionally with an expiry.
app.MapPost("/links", (CreateLinkRequest request, ILinkStore store, HttpContext ctx) =>
{
    if (!UrlValidator.IsValid(request.Url))
        return Results.Problem("Target URL must be an absolute http/https URL.", statusCode: StatusCodes.Status400BadRequest);

    var link = store.Create(request.Url, request.ExpiresAt);
    var shortUrl = $"{ctx.Request.Scheme}://{ctx.Request.Host}/{link.Code}";
    return Results.Ok(new CreateLinkResponse(link.Code, shortUrl));
});

// Resolve a short code: 404 unknown, 410 expired, otherwise record the click and 302 redirect.
app.MapGet("/{code}", (string code, ILinkStore store) =>
{
    var link = store.Get(code);
    if (link is null) return Results.NotFound();
    if (link.IsExpired(DateTimeOffset.UtcNow)) return Results.StatusCode(StatusCodes.Status410Gone);
    store.RecordClick(code, DateTimeOffset.UtcNow);
    return Results.Redirect(link.TargetUrl, permanent: false);
});

// Click analytics for a link.
app.MapGet("/links/{code}/stats", (string code, ILinkStore store) =>
{
    var stats = store.GetStats(code);
    return stats is null ? Results.NotFound() : Results.Ok(stats);
});

app.Run();

public record CreateLinkRequest(string Url, DateTimeOffset? ExpiresAt = null);
public record CreateLinkResponse(string Code, string ShortUrl);
